## Notes

- **Webhook delivery is not guaranteed exactly-once.** Design your handler to be idempotent — the same event may be delivered more than once.
- **Span start detection:** `span === true && startTimestamp === endTimestamp` indicates start. `span === true && startTimestamp !== endTimestamp` indicates end.
- **Custom event types** must be registered with Eagle Eye. Use reverse-domain notation: `com.yourcompany.serviceName.eventName.v1`.
- **`creatorId`** identifies your service, not the actor. Use a stable, unique string like `com.yourcompany.faceRecognition`.
- **Timestamps in snapshots:** The `X-Een-Timestamp` response header contains the actual frame time, which may differ slightly from the requested time. Use this for accurate metadata.
- **SSE alternative:** Set `deliveryConfig.type = "serverSentEvents.v1"` for browser-based real-time subscriptions. SSE subscriptions are `temporary` (session-scoped) rather than `persistent`.

interface SubscriptionResponse {
  id: string;
  lifeCycle: "persistent" | "temporary";
}

async function subscribeToEvents(
  accessToken: string,
  baseUrl: string,
  webhookUrl: string,
  webhookSecret: string,
  cameraIds: string[],
  eventTypes: string[]
): Promise<SubscriptionResponse> {
  const response = await fetch(
    `https://${baseUrl}/api/v3.0/eventSubscriptions`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${accessToken}`,
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: JSON.stringify({
        deliveryConfig: {
          type: "webhook.v1",
          url: webhookUrl,
          authorizationHeader: `Bearer ${webhookSecret}`,
        },
        filters: [
          {
            resourceType: "camera",
            resourceIds: cameraIds,
            types: eventTypes,
          },
        ],
      }),
    }
  );
  if (!response.ok) throw new Error(`Subscribe failed: ${response.status}`);
  return response.json();
}

async function getRecordedSnapshot(
  accessToken: string,
  baseUrl: string,
  deviceId: string,
  timestamp: string, // ISO 8601 with +00:00
  recordedType: "main" | "preview" = "main"
): Promise<{ jpeg: ArrayBuffer; actualTimestamp: string; nextToken?: string }> {
  const params = new URLSearchParams({
    deviceId,
    recordedType,
    timestampGreaterOrEqual: timestamp,
  });
  const response = await fetch(
    `https://${baseUrl}/api/v3.0/media/recordedImage.jpeg?${params}`,
    { headers: { Authorization: `Bearer ${accessToken}` } }
  );
  if (!response.ok) throw new Error(`Snapshot failed: ${response.status}`);
  return {
    jpeg: await response.arrayBuffer(),
    actualTimestamp: response.headers.get("X-Een-Timestamp") ?? timestamp,
    nextToken: response.headers.get("X-Een-NextToken") ?? undefined,
  };
}

async function sampleSpanFrames(
  accessToken: string,
  baseUrl: string,
  deviceId: string,
  startTs: string,
  endTs: string,
  numSamples = 5
): Promise<ArrayBuffer[]> {
  const start = new Date(startTs).getTime();
  const end = new Date(endTs).getTime();
  const duration = end - start;
  const frames: ArrayBuffer[] = [];

  for (let i = 0; i < numSamples; i++) {
    const offset = duration * (i / Math.max(numSamples - 1, 1));
    const ts = new Date(start + offset).toISOString().replace(/Z$/, "+00:00");
    const { jpeg } = await getRecordedSnapshot(accessToken, baseUrl, deviceId, ts);
    frames.push(jpeg);
  }
  return frames;
}

async function createDerivedEvent(
  accessToken: string,
  baseUrl: string,
  params: {
    actorId: string;
    actorAccountId: string;
    accountId: string;
    startTs: string;
    endTs: string;
    creatorId: string;
    eventType: string;
    dataSchemas: string[];
    data: Record<string, unknown>[];
  }
): Promise<{ id: string }> {
  const response = await fetch(`https://${baseUrl}/api/v3.0/events`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      startTimestamp: params.startTs,
      endTimestamp: params.endTs,
      span: params.startTs !== params.endTs,
      accountId: params.accountId,
      actorId: params.actorId,
      actorAccountId: params.actorAccountId,
      actorType: "camera",
      creatorId: params.creatorId,
      type: params.eventType,
      dataSchemas: params.dataSchemas,
      data: params.data,
    }),
  });
  if (!response.ok) throw new Error(`createEvent failed: ${response.status}`);
  return response.json();
}

// Webhook handler — detect span start vs end
function handleWebhookEvent(event: {
  span: boolean;
  startTimestamp: string;
  endTimestamp: string;
  actorId: string;
  type: string;
}) {
  const isSpanEnd =
    event.span && event.startTimestamp !== event.endTimestamp;
  const isSpanStart =
    event.span && event.startTimestamp === event.endTimestamp;

  if (isSpanEnd) {
    // Full window available — sample and enrich
    sampleSpanFrames(accessToken, baseUrl, event.actorId,
      event.startTimestamp, event.endTimestamp)
      .then(frames => {
        // run inference on frames, then create derived event
      });
  }
}

# Core Function Group 7: User & Account Management

## Purpose

Create, read, update, and delete users on an account; define roles with specific permission sets; and assign those roles to users. These functions are the foundation for any admin dashboard, partner onboarding workflow, or multi-tenant integration that needs to manage who has access to what.

---

## Key Concepts

**Users** are individuals with login credentials tied to an account. A new user is created in `pending` state and receives a verification email. They become `active` after verifying.

**Roles** are named permission sets. Instead of assigning permissions directly to users, you define roles (e.g. "Operator", "Auditor", "Admin") and then assign users to roles. Multiple roles can be assigned to one user.

**Role Assignments** are the links between users and roles. Manage them in bulk via `:bulkCreate` and `:bulkDelete`.

> If your account uses the Roles API for permission management, user `permissions` fields become read-only — all permission changes must go through role assignments.

---

## Users

### List Users

```
GET https://{baseUrl}/api/v3.0/users
Authorization: Bearer {access_token}
```

**Key query parameters:**

| Parameter | Description |
|---|---|
| `email__contains` | Filter by partial email match |
| `firstName__contains` | Filter by partial first name |
| `lastName__contains` | Filter by partial last name |
| `id__in` | Comma-separated list of specific user IDs |
| `status.loginStatus__in` | Filter by status: `active`, `pending`, `inactive` |
| `permissions.administrator` | `true` to return only admins |
| `include` | Additional fields to include per user |
| `pageSize`, `pageToken` | Pagination |
| `sort` | Sort field, prefix `-` for descending |
| `q` | Free-text search |

**Response:**
```json
{
  "results": [
    {
      "id": "ca0f61ab",
      "email": "user@example.com",
      "firstName": "Jane",
      "lastName": "Smith",
      "status": { "loginStatus": "active" },
      "permissions": { "administrator": false }
    }
  ],
  "nextPageToken": "",
  "totalSize": 42
}
```

### Get Current User

```
GET https://{baseUrl}/api/v3.0/users/self
Authorization: Bearer {access_token}
```

Returns the authenticated user's profile. Useful for determining the account context after login.

### Create User

```
POST https://{baseUrl}/api/v3.0/users
Authorization: Bearer {access_token}
Content-Type: application/json
```

```json
{
  "firstName": "Jane",
  "lastName": "Smith",
  "email": "jane.smith@example.com"
}
```

- User is created in `pending` state
- EEN sends a verification email automatically
- User becomes `active` after verifying

**Response:** `201 Created` with full user object including assigned `id`.

### Update User

```
PATCH https://{baseUrl}/api/v3.0/users/{userId}
Authorization: Bearer {access_token}
Content-Type: application/json
```

Send only the fields to change. Returns `204 No Content` on success.

### Delete User

```
DELETE https://{baseUrl}/api/v3.0/users/{userId}
Authorization: Bearer {access_token}
```

Returns `204 No Content`. Removes user from account.

---

## Roles

### List Roles

```
GET https://{baseUrl}/api/v3.0/roles
Authorization: Bearer {access_token}
```

| Parameter | Description |
|---|---|
| `roleName__contains` | Filter by partial name |
| `id__in` | Specific role IDs |
| `include` | Additional fields |
| `pageSize`, `pageToken` | Pagination |

**Response:**
```json
{
  "results": [
    {
      "id": "role-abc123",
      "name": "Camera Operator",
      "permissions": ["cameras.view", "feeds.view"],
      "createTimestamp": "2024-01-15T10:00:00.000+00:00"
    }
  ]
}
```

### Create Role

```
POST https://{baseUrl}/api/v3.0/roles
Authorization: Bearer {access_token}
Content-Type: application/json
```

```json
{
  "name": "Camera Operator",
  "description": "Can view cameras and live feeds",
  "permissions": ["cameras.view", "feeds.view", "media.view"]
}
```

**Response:** `201 Created` with role object including `id`.

### Update Role

```
PATCH https://{baseUrl}/api/v3.0/roles/{roleId}
```

Send only fields to change (`name`, `description`, `permissions`). Returns `204 No Content`.

### Delete Role

```
DELETE https://{baseUrl}/api/v3.0/roles/{roleId}
```

A role can only be deleted if it has no active assignments. Returns `204 No Content`.

---

## Role Assignments

### List Assignments

```
GET https://{baseUrl}/api/v3.0/roleAssignments
Authorization: Bearer {access_token}
```

| Parameter | Description |
|---|---|
| `userId__in` | Filter by user IDs |
| `roleId__in` | Filter by role IDs |
| `roleName__contains` | Filter by role name |
| `self` | `true` to return only the current user's assignments |

### Bulk Create Assignments

```
POST https://{baseUrl}/api/v3.0/roleAssignments:bulkCreate
Authorization: Bearer {access_token}
Content-Type: application/json
```

```json
[
  { "userId": "ca0f61ab", "roleId": "role-abc123" },
  { "userId": "ca0f61ab", "roleId": "role-def456" }
]
```

### Bulk Delete Assignments

```
POST https://{baseUrl}/api/v3.0/roleAssignments:bulkDelete
Authorization: Bearer {access_token}
Content-Type: application/json
```

Same body shape as bulk create — sends the list of assignments to remove.

---

