use reqwest::Client;
use serde::{Deserialize, Serialize};
use std::time::{Duration, Instant};
use tokio::time::sleep;

#[derive(Deserialize)]
struct ExportResponse {
    #[serde(rename = "jobId")]
    job_id: String,
}

#[derive(Deserialize)]
struct Job {
    id: String,
    state: String,
}

pub async fn create_export(
    access_token: &str,
    base_url: &str,
    device_id: &str,
    start_ts: &str,
    end_ts: &str,
    export_type: &str,
    name: &str,
) -> Result<String, reqwest::Error> {
    let body = serde_json::json!({
        "deviceId": device_id,
        "type": export_type,
        "period": { "startTimestamp": start_ts, "endTimestamp": end_ts },
        "osd": { "timeZone": "UTC" },
        "info": { "name": name, "directory": "/exports" },
    });

    let response: ExportResponse = Client::new()
        .post(format!("https://{}/api/v3.0/exports", base_url))
        .bearer_auth(access_token)
        .json(&body)
        .send()
        .await?
        .error_for_status()?
        .json()
        .await?;

    Ok(response.job_id)
}

pub async fn poll_job(
    access_token: &str,
    base_url: &str,
    job_id: &str,
    interval: Duration,
    timeout: Duration,
) -> Result<(), Box<dyn std::error::Error>> {
    let client = Client::new();
    let deadline = Instant::now() + timeout;

    loop {
        let job: Job = client
            .get(format!("https://{}/api/v3.0/jobs/{}", base_url, job_id))
            .bearer_auth(access_token)
            .send()
            .await?
            .error_for_status()?
            .json()
            .await?;

        match job.state.as_str() {
            "done" => return Ok(()),
            "failed" | "cancelled" => {
                return Err(format!("Job {} ended with state: {}", job_id, job.state).into())
            }
            _ => {}
        }

        if Instant::now() >= deadline {
            return Err("Export job timed out".into());
        }
        sleep(interval).await;
    }
}
